import express from 'express';
import path from 'node:path';
import { stat } from 'node:fs/promises';

export function createApp({ root = process.env.FILES_ROOT ?? path.resolve('files') } = {}) {
  const app = express();
  const base = path.resolve(root);
  app.use(express.json());

  app.get('/health', (req, res) => {
    res.json({ ok: true });
  });

  // Express 5: named wildcard; req.params.path is an array of segments.
  app.get('/files/*path', async (req, res) => {
    const segments = req.params.path;
    const rel = segments.join('/');
    const full = path.resolve(base, rel);
    if (segments.includes('..') || segments.some((s) => s.includes('\0')) ||
        (full !== base && !full.startsWith(base + path.sep))) {
      return res.status(400).json({ error: 'Invalid path' });
    }
    let s;
    try {
      s = await stat(full);
    } catch (err) {
      if (err.code === 'ENOENT' || err.code === 'ENOTDIR') {
        return res.status(404).json({ error: 'Not Found' });
      }
      throw err; // Express 5 forwards async rejections to the error handler
    }
    res.json({
      path: rel,
      name: path.basename(full),
      type: s.isDirectory() ? 'directory' : 'file',
      size: s.size,
      modified: s.mtime.toISOString(),
      created: s.birthtime.toISOString(),
    });
  });

  app.use((req, res) => {
    res.status(404).json({ error: 'Not Found' });
  });

  app.use((err, req, res, next) => {
    if (res.headersSent) return next(err);
    const status = err.status ?? err.statusCode ?? 500;
    res.status(status).json({ error: status === 500 ? 'Internal Server Error' : err.message });
  });

  return app;
}

export const app = createApp();
EOF
